-- SwiftDictionary Update 2.4.0 — original Advanced Quiz question bank (32 items).
-- Original learning content and Simplified Chinese translations.
begin;
with seed(question_id,source_lesson_id,topic_id,difficulty,prompt_learning,prompt_zh,a_learning,a_zh,b_learning,b_zh,c_learning,c_zh,d_learning,d_zh,correct_option_id,explanation_learning,explanation_zh) as (
 values
('a-hedge-01','a-hedging','academic-professional-english','advanced','Which sentence uses cautious academic language rather than making an absolute claim?','哪个句子使用谨慎的学术表达，而不是作出绝对断言？','This proves that the method always works.,这证明该方法总是有效。','The findings suggest that the method may be effective.,研究结果表明该方法可能有效。','There is no doubt that the method works in every case.,毫无疑问，该方法在所有情况下都有效。','The method is certainly perfect.,该方法肯定是完美的。','b','“Suggest” and “may” hedge the claim and leave room for uncertainty.','“suggest”和“may”弱化了断言，为不确定性留出空间。'),
('a-hedge-02','a-hedging','academic-professional-english','advanced','Choose the best hedge: “The decline ___ be linked to seasonal demand.”','选择最合适的谨慎表达：“The decline ___ be linked to seasonal demand.”','must,必定','might,可能','cannot,不可能','will certainly,肯定将会','b','Might presents a possible explanation without claiming certainty.','might表示一种可能的解释，而不是确定结论。'),
('a-hedge-03','a-hedging','academic-professional-english','advanced','Which phrase most clearly signals a limited claim?','哪个短语最明确地表示结论范围有限？','in all circumstances,在所有情况下','without exception,毫无例外','in this sample,在这个样本中','universally,普遍地','c','“In this sample” limits the conclusion to the group actually examined.','“In this sample”将结论限定在实际研究的样本范围内。'),
('a-hedge-04','a-hedging','academic-professional-english','advanced','Choose the sentence with the most appropriate level of certainty for preliminary evidence.','选择最适合初步证据确定程度的句子。','The early results appear to support the proposal.,初步结果似乎支持这项提议。','The early results conclusively establish the proposal.,初步结果确凿地证明了这项提议。','The early results guarantee success.,初步结果保证成功。','The proposal is unquestionably correct.,这项提议无疑是正确的。','a','“Appear to support” appropriately signals that the evidence is preliminary.','“似乎支持”恰当地表明证据仍处于初步阶段。'),
('a-hedge-05','a-hedging','academic-professional-english','advanced','Which expression indicates an approximate rather than exact quantity?','哪个表达表示大约的数量，而不是精确数量？','exactly 250,正好250','no fewer than 250,不少于250','approximately 250,大约250','precisely 250,精确地250','c','Approximately marks the figure as an estimate.','approximately表示该数字是估算值。'),
('a-hedge-06','a-hedging','academic-professional-english','advanced','Choose the most measured conclusion.','选择措辞最审慎的结论。','The policy caused every improvement.,这项政策造成了所有改善。','The policy may have contributed to the improvement.,这项政策可能促成了改善。','The policy is the only possible explanation.,这项政策是唯一可能的解释。','The policy definitely explains all outcomes.,这项政策肯定解释了所有结果。','b','“May have contributed” acknowledges a possible role without claiming sole causation.','“可能促成”承认其可能发挥作用，但不声称它是唯一原因。'),
('a-inversion-01','a-inversion','advanced-grammar','advanced','Choose the correct inversion after “Rarely”.','选择“Rarely”后正确的倒装结构。','Rarely we see such care.,Rarely we see such care.','Rarely do we see such care.,Rarely do we see such care.','Rarely see we such care.,Rarely see we such care.','Rarely did we sees such care.,Rarely did we sees such care.','b','A negative or restrictive adverb at the beginning commonly triggers auxiliary–subject inversion.','否定或限制性副词置于句首时，通常触发助动词与主语倒装。'),
('a-inversion-02','a-inversion','advanced-grammar','advanced','Complete the structure: “Not only ___ the deadline, but she also improved the design.”','完成结构：“Not only ___ the deadline, but she also improved the design.”','she met,she met','did she meet,did she meet','she did met,she did met','met she,met she','b','When “Not only” begins the clause, use inversion: did + subject + base verb.','“Not only”置于从句开头时使用倒装：did + 主语 + 动词原形。'),
('a-inversion-03','a-inversion','advanced-grammar','advanced','Choose the grammatically correct sentence beginning with “Under no circumstances”.','选择以“Under no circumstances”开头且语法正确的句子。','Under no circumstances you should reveal the code.,在任何情况下你都不应该透露代码。','Under no circumstances should you reveal the code.,在任何情况下你都不应该透露代码。','Under no circumstances should reveal you the code.,在任何情况下应该透露你代码。','Under no circumstances you reveal should the code.,在任何情况下你透露应该代码。','b','The fronted negative phrase requires inversion: should you reveal.','前置的否定短语要求倒装：should you reveal。'),
('a-inversion-04','a-inversion','advanced-grammar','advanced','Choose the correct “No sooner” construction.','选择正确的“No sooner”结构。','No sooner the train had left than it began to rain.,火车刚开走就开始下雨。','No sooner had the train left than it began to rain.,火车刚开走就开始下雨。','No sooner did the train left than it began to rain.,火车刚开走就开始下雨。','No sooner has the train leave than it began to rain.,火车刚开走就开始下雨。','b','The pattern is “No sooner had + subject + past participle + than”.','结构为“No sooner had + 主语 + 过去分词 + than”。'),
('a-inversion-05','a-inversion','advanced-grammar','advanced','Which sentence correctly uses inversion after “Little”?','哪个句子正确使用了“Little”引导的倒装？','Little I knew about the risks.,我对风险知之甚少。','Little did I know about the risks.,我当时并不知道这些风险。','Little knew I about the risks.,我对风险知之甚少。','Little I did knew about the risks.,我对风险知之甚少。','b','“Little” at the beginning gives a negative meaning and is followed by did + subject + base verb.','句首的“Little”带有否定含义，后面接did + 主语 + 动词原形。'),
('a-inversion-06','a-inversion','advanced-grammar','advanced','Choose the correct inversion after “Only after the meeting”.','选择“Only after the meeting”后正确的倒装句。','Only after the meeting we understood the issue.,只有会议结束后我们才理解问题。','Only after the meeting did we understand the issue.,只有会议结束后我们才理解问题。','Only after the meeting understood we the issue.,只有会议结束后我们才理解问题。','Only after the meeting we did understood the issue.,只有会议结束后我们才理解问题。','b','When an “Only + adverbial” phrase is fronted, the main clause normally uses inversion.','“Only + 状语”短语置于句首时，主句通常使用倒装。'),
('a-inversion-07','a-inversion','advanced-grammar','advanced','Which sentence correctly uses “So” for emphasis?','哪个句子正确使用“So”进行强调？','So difficult the task was that we asked for help.,任务如此困难，以至于我们寻求帮助。','So difficult was the task that we asked for help.,任务如此困难，以至于我们寻求帮助。','So was difficult the task that we asked for help.,任务如此困难，以至于我们寻求帮助。','So difficult did the task was that we asked for help.,任务如此困难，以至于我们寻求帮助。','b','The pattern is “So + adjective + be + subject + that”.','结构为“So + 形容词 + be + 主语 + that”。'),
('a-mixed-01','a-mixed-conditionals','advanced-grammar','advanced','Choose the mixed conditional linking a past event to a present result.','选择连接过去事件与现在结果的混合条件句。','If I had accepted the offer, I would live abroad now.,如果我当时接受了邀请，我现在就住在国外了。','If I accept the offer, I would live abroad now.,如果我接受邀请，我现在就住在国外了。','If I accepted the offer, I would have lived abroad now.,如果我接受邀请，我现在就住在国外了。','If I had accepted the offer, I will live abroad now.,如果我当时接受邀请，我现在将住在国外。','a','A past unreal condition uses past perfect; its present result uses would + base verb.','过去的非真实条件使用过去完成时；现在的结果使用would + 动词原形。'),
('a-mixed-02','a-mixed-conditionals','advanced-grammar','advanced','Choose the mixed conditional where a present characteristic explains a past result.','选择由现在的特征解释过去结果的混合条件句。','If she were more organised, she would not have missed the deadline.,如果她更有条理，当时就不会错过截止日期。','If she had been more organised, she would not miss the deadline yesterday.,如果她当时更有条理，昨天就不会错过截止日期。','If she is more organised, she would not have missed the deadline.,如果她更有条理，当时就不会错过截止日期。','If she were more organised, she will not miss the deadline.,如果她更有条理，她就不会错过截止日期。','a','A present unreal state (were more organised) can explain a past consequence (would not have missed).','现在的非真实状态（were more organised）可以解释过去的结果（would not have missed）。'),
('a-mixed-03','a-mixed-conditionals','advanced-grammar','advanced','Complete the sentence: “If he had taken the earlier train, he ___ here by now.”','完成句子：“If he had taken the earlier train, he ___ here by now.”','would be,would be','will be,will be','would have been,would have been','is,is','a','The past condition has a present result, so use would be.','过去的条件产生现在的结果，因此使用would be。'),
('a-mixed-04','a-mixed-conditionals','advanced-grammar','advanced','Which sentence correctly expresses a past condition with a present consequence?','哪个句子正确表达过去的条件及其现在的后果？','If I had saved more, I would have enough for the trip now.,如果我当时存多一点钱，现在就有足够的钱旅行了。','If I save more, I would have enough for the trip now.,如果我多存钱，现在就有足够的钱旅行了。','If I had saved more, I will have enough for the trip now.,如果我当时存多一点，现在就会有足够的钱旅行。','If I saved more, I would have had enough for the trip now.,如果我存多一点，现在就会有足够的钱旅行。','a','The if-clause refers to an unreal past action; the result clause describes the current situation.','if从句指过去未发生的动作；结果从句描述现在的情况。'),
('a-mixed-05','a-mixed-conditionals','advanced-grammar','advanced','Choose the best completion: “If they had not moved away, we ___ neighbours today.”','选择最佳补全：“If they had not moved away, we ___ neighbours today.”','are still,仍然是','would still be,仍然会是','would still have been,仍然会是（过去）','will still be,仍然将是','b','A past unreal condition affects the present, so use would + base verb.','过去的非真实条件影响现在，因此使用would + 动词原形。'),
('a-mixed-06','a-mixed-conditionals','advanced-grammar','advanced','Which sentence has a correct mixed-conditional time relationship?','哪个句子的混合条件时间关系正确？','If I were less cautious, I would have invested last year.,如果我没那么谨慎，去年就会投资了。','If I had been less cautious, I would invest last year.,如果我当时没那么谨慎，我去年就会投资。','If I am less cautious, I would have invested last year.,如果我没那么谨慎，去年就会投资了。','If I were less cautious, I will have invested last year.,如果我没那么谨慎，去年就会投资了。','a','A continuing present trait (were less cautious) can explain a past decision (would have invested).','持续到现在的特征（were less cautious）可以解释过去的决定（would have invested）。'),
('a-mixed-07','a-mixed-conditionals','advanced-grammar','advanced','Choose the correct form: “If the building were better insulated, energy costs ___ last winter.”','选择正确形式：“If the building were better insulated, energy costs ___ last winter.”','would be lower,会更低','would have been lower,本来会更低','will have been lower,将会更低','had been lower,曾经更低','b','A present unreal condition is linked to a past result, requiring would have + past participle.','现在的非真实条件连接过去结果，需要would have + 过去分词。'),
('a-idiom-01','a-idioms','idioms-fixed-expressions','advanced','What does “to add fuel to the fire” mean?','“add fuel to the fire”是什么意思？','to make a problem or conflict worse,使问题或冲突恶化','to solve a disagreement,解决分歧','to avoid a difficult topic,避开难题','to celebrate an achievement,庆祝成就','a','The idiom means to make an already difficult or angry situation worse.','这个习语表示让本已困难或紧张的情况变得更糟。'),
('a-idiom-02','a-idioms','idioms-fixed-expressions','advanced','If someone “gets cold feet” before a presentation, what happens?','如果某人在演讲前“gets cold feet”，会发生什么？','They become more confident.,他们变得更有信心。','They become nervous and hesitate.,他们感到紧张并犹豫。','They forget the topic completely.,他们完全忘记主题。','They arrive very early.,他们很早到达。','b','“Get cold feet” means to become nervous and lose confidence before doing something.','“Get cold feet”表示在做某事前感到紧张、失去信心。'),
('a-idiom-03','a-idioms','idioms-fixed-expressions','advanced','What does “the ball is in your court” mean?','“the ball is in your court”是什么意思？','You have lost an opportunity.,你失去了机会。','It is now your turn or responsibility to act.,现在轮到你采取行动或承担责任。','You should stop participating.,你应该停止参与。','The decision has already been made.,决定已经作出。','b','The idiom means the next move or decision is now yours.','这个习语表示下一步行动或决定现在由你负责。'),
('a-idiom-04','a-idioms','idioms-fixed-expressions','advanced','Choose the meaning of “to read between the lines.”','选择“read between the lines”的意思。','to read a text aloud,大声朗读文本','to understand an implied meaning,理解言外之意','to skip unimportant paragraphs,跳过不重要的段落','to compare two documents,比较两份文件','b','It means to infer a meaning that is suggested but not stated directly.','它表示推断暗示但没有直接说出的含义。'),
('a-idiom-05','a-idioms','idioms-fixed-expressions','advanced','What does “a blessing in disguise” describe?','“a blessing in disguise”描述什么？','a problem that leads to an unexpected benefit,带来意外好处的问题','a gift that is hidden,被藏起来的礼物','a success that was planned,计划之中的成功','a risk that cannot be avoided,无法避免的风险','a','It describes something that first seems bad but later brings a benefit.','它指一件起初看似不好的事，后来却带来好处。'),
('a-idiom-06','a-idioms','idioms-fixed-expressions','advanced','If a plan “goes out of the window,” what happens to it?','如果一个计划“goes out of the window”，它会怎样？','It is carefully improved.,它得到仔细改进。','It is abandoned or ignored.,它被放弃或忽视。','It is publicly announced.,它被公开宣布。','It becomes more expensive.,它变得更昂贵。','b','The idiom means a plan, rule or idea is no longer followed.','这个习语表示计划、规则或想法不再被遵循。'),
('a-near-01','a-near-synonyms','precise-vocabulary','advanced','Choose “economic” or “economical”: “The report examines the ___ effects of the policy.”','选择“economic”或“economical”：“The report examines the ___ effects of the policy.”','economic,经济方面的','economical,节省的','economy,经济','economically,在经济上','a','Economic relates to the economy; economical means avoiding waste or saving money.','economic与经济有关；economical表示节省、不浪费。'),
('a-near-02','a-near-synonyms','precise-vocabulary','advanced','Which verb means to suggest an idea indirectly?','哪个动词表示间接暗示某个想法？','infer,推断','imply,暗示','assume,假设','conclude,得出结论','b','A speaker or writer implies; a listener or reader infers.','说话者或作者imply（暗示）；听者或读者infer（推断）。'),
('a-near-03','a-near-synonyms','precise-vocabulary','advanced','Choose the correct word: “The medicine may ___ your ability to concentrate.”','选择正确的词：“The medicine may ___ your ability to concentrate.”','effect,效果','affect,影响','effective,有效的','affection,喜爱','b','Affect is usually the verb meaning to influence; effect is usually a noun.','affect通常是表示影响的动词；effect通常是名词。'),
('a-near-04','a-near-synonyms','precise-vocabulary','advanced','Which word describes something that continues without interruption?','哪个词描述没有中断、持续进行的事物？','continual,反复发生的','continuous,连续不断的','constant,恒定的','continually,不断地','b','Continuous means without interruption; continual often suggests repeated occurrences.','continuous表示没有中断；continual通常表示反复发生。'),
('a-near-05','a-near-synonyms','precise-vocabulary','advanced','Choose the correct word: “The new process is more ___ because it uses less energy.”','选择正确的词：“The new process is more ___ because it uses less energy.”','efficient,高效的','effective,有效的','effectual,奏效的','affective,情感的','a','Efficient means achieving a result with little waste of time, energy or resources.','efficient表示以较少的时间、能源或资源达成结果。'),
('a-near-06','a-near-synonyms','precise-vocabulary','advanced','Which word means to make something less severe?','哪个词表示减轻某事的严重程度？','aggravate,加重','alleviate,缓解','allocate,分配','anticipate,预期','b','Alleviate means to reduce pain, difficulty or severity.','alleviate表示减轻痛苦、困难或严重程度。')
),
variants as (
 select question_id||'-zh' as question_id,source_lesson_id,topic_id,difficulty,'zh'::text as translation_language_code,
 prompt_learning,prompt_zh as prompt_translation,
 jsonb_build_array(jsonb_build_object('id','a','learning_text',a_learning,'translation_text',a_zh),jsonb_build_object('id','b','learning_text',b_learning,'translation_text',b_zh),jsonb_build_object('id','c','learning_text',c_learning,'translation_text',c_zh),jsonb_build_object('id','d','learning_text',d_learning,'translation_text',d_zh)) as options,
 correct_option_id,explanation_learning,explanation_zh as explanation_translation
 from seed
 union all
 select question_id||'-en',source_lesson_id,topic_id,difficulty,'en',prompt_learning,prompt_learning,
 jsonb_build_array(jsonb_build_object('id','a','learning_text',a_learning,'translation_text',a_learning),jsonb_build_object('id','b','learning_text',b_learning,'translation_text',b_learning),jsonb_build_object('id','c','learning_text',c_learning,'translation_text',c_learning),jsonb_build_object('id','d','learning_text',d_learning,'translation_text',d_learning)),
 correct_option_id,explanation_learning,explanation_learning from seed
)
insert into private.quiz_question_bank
(question_id,revision,learning_language_code,translation_language_code,source_lesson_id,topic_id,difficulty,prompt_learning,prompt_translation,options,correct_option_id,explanation_learning,explanation_translation,status,approved_at)
select question_id,1,'en',translation_language_code,source_lesson_id,topic_id,difficulty,prompt_learning,prompt_translation,options,correct_option_id,explanation_learning,explanation_translation,'approved',pg_catalog.now()
from variants on conflict (question_id,revision) do nothing;
commit;
